  const TL = window.TL, AMP = window.AMP || [], FPS = TL.fps;
  const LN = Object.fromEntries(TL.lines.map(l => [l.id, l]));
  const $ = id => document.getElementById(id);
  const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
  const lerp = (a, b, k) => a + (b - a) * k;
  const eio = k => (k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2);
  const eout = k => 1 - Math.pow(1 - k, 3);
  const back = k => { const c1 = 1.7, c3 = c1 + 1; return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2); };
  const P = (t, a, d) => clamp((t - a) / d);
  const S = id => LN[id].start, E = id => LN[id].end;
  /* time of the first word in a line that starts with `w` (case-insensitive), after an optional index */
  const W = (id, w, from = 0) => {
    const ws = LN[id].words;
    for (let i = from; i < ws.length; i++) if (ws[i].w.toLowerCase().replace(/[^a-z0-9$]/g, "").startsWith(w.toLowerCase())) return ws[i].s;
    return LN[id].start;
  };
  const pop = (t, a, d = .45) => { const k = P(t, a, d); return { o: clamp(k * 2.2), s: Math.max(0, back(k)), y: (1 - eout(k)) * 22 }; };
  const st = (p, extra = "") => `opacity:${p.o};transform:translateY(${p.y}px) scale(${.92 + .08 * p.s}) ${extra};`;

  /* -------- static stars, painted once from a fixed seed -------- */
  (function stars() {
    const c = $("stars").getContext("2d");
    let s = 7;
    const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;
    for (let i = 0; i < 170; i++) {
      const x = rnd() * 1920, y = rnd() * 760, r = rnd() * 1.6 + .3;
      c.fillStyle = `rgba(255,255,255,${.18 + rnd() * .5})`;
      c.beginPath(); c.arc(x, y, r, 0, 6.283); c.fill();
    }
  })();

  /* -------- icons -------- */
  const I = {
    chat: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12a8 8 0 0 1-11.6 7.1L4 20l1-4.6A8 8 0 1 1 21 12z"/></svg>',
    cash: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="6" width="19" height="12" rx="2"/><circle cx="12" cy="12" r="2.6"/></svg>',
    code: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="m8 6-6 6 6 6M16 6l6 6-6 6"/></svg>',
    eye: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>',
    find: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg>',
    usd: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20M17 6.5C17 4.6 14.8 4 12 4S7 4.9 7 7.2c0 4.8 10 2.6 10 7.6 0 2.4-2.3 3.2-5 3.2s-5.2-.8-5.2-3"/></svg>',
    fix: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5"/></svg>',
    check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><path d="m4 12.5 5 5L20 6.5"/></svg>',
    msg: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 4h16v12H8l-4 4z"/></svg>',
    hand: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 11V6a2 2 0 0 0-4 0v5M14 10V4a2 2 0 0 0-4 0v6M10 10.5V6a2 2 0 0 0-4 0v8"/><path d="M18 8a2 2 0 1 1 4 0v6a8 8 0 0 1-8 8h-2c-2.8 0-4.5-.9-6-2.4l-3.6-3.6a2 2 0 0 1 2.8-2.8L7 15"/></svg>',
    bell: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.9 1.9 0 0 0 3.4 0"/><path d="m2 2 20 20"/></svg>',
  };
  const LOGO = {
    neatlogs: '<img src="assets/img/logo-neatlogs.png" alt="neatlogs"/>',
    entire: '<img src="assets/img/logo-entire.svg" alt="Entire"/>',
    cfo: '<img src="assets/img/logo-cfo.svg" alt="cfo.ai"/>',
  };
  const tagHTML = (logo, label) => `<span class="tag">${logo ? LOGO[logo].replace("<img ", '<img class="lg-w" ') : ""}${label ? `<span>${label}</span>` : ""}</span>`;

  /* -------- which scene / act are we in -------- */
  const lineAt = t => { let c = null; for (const l of TL.lines) if (t >= l.start - .25) c = l; return c; };
  const ACT2 = S("L04") - .5, ACT4 = S("L15") - .35, CLOSE = S("L19") - .45;

  /* -------- ghost face (same rig as the published explainer) -------- */
  const EL = { x: 731, y: 471, rx: 47, ry: 64 }, ER = { x: 975, y: 442, rx: 39, ry: 58 }, MO = { x: 878, y: 506 };
  function face(o) {
    const eye = (E, open, closedStyle) => {
      if (o.mood === "happy" || closedStyle) return `<path d="M${E.x - E.rx * .8} ${E.y + 8} Q${E.x} ${E.y - E.ry * .55} ${E.x + E.rx * .8} ${E.y + 8}" stroke="#fff" stroke-width="15" fill="none" stroke-linecap="round"/>`;
      if (open < .22) return `<path d="M${E.x - E.rx * .85} ${E.y + 6} Q${E.x} ${E.y + 22} ${E.x + E.rx * .85} ${E.y + 6}" stroke="#fff" stroke-width="13" fill="none" stroke-linecap="round"/>`;
      const ry = E.ry * open * (o.wide ? 1.12 : 1), rx = E.rx * (o.wide ? 1.08 : 1);
      const px = E.x + o.gx * E.rx * .38, py = E.y + o.gy * E.ry * .3 + E.ry * .08;
      return `<ellipse cx="${E.x}" cy="${E.y}" rx="${rx}" ry="${ry}" fill="#fff"/><clipPath id="c${E.x}"><ellipse cx="${E.x}" cy="${E.y}" rx="${rx}" ry="${ry}"/></clipPath>
        <g clip-path="url(#c${E.x})"><ellipse cx="${px}" cy="${py}" rx="${rx * .56}" ry="${E.ry * .62}" fill="#0d0c12"/><circle cx="${px + rx * .18}" cy="${py - E.ry * .22}" r="${rx * .17}" fill="#fff"/></g>`;
    };
    let s = eye(EL, o.open, false) + eye(ER, o.open, o.wink);
    if (o.mood === "worried") s += `<path d="M${EL.x - 40} ${EL.y - 92} L${EL.x + 30} ${EL.y - 78}" stroke="#fff" stroke-width="12" stroke-linecap="round"/><path d="M${ER.x + 34} ${ER.y - 88} L${ER.x - 30} ${ER.y - 76}" stroke="#fff" stroke-width="11" stroke-linecap="round"/>`;
    if (o.brow) s += `<path d="M${EL.x - 44} ${EL.y - 104} Q${EL.x} ${EL.y - 128} ${EL.x + 40} ${EL.y - 104}" stroke="#fff" stroke-width="12" fill="none" stroke-linecap="round"/><path d="M${ER.x - 36} ${ER.y - 98} Q${ER.x} ${ER.y - 122} ${ER.x + 38} ${ER.y - 98}" stroke="#fff" stroke-width="11" fill="none" stroke-linecap="round"/>`;
    if (o.amp > .07) {
      const h = 18 + 52 * clamp(o.amp), w = 40 + 10 * clamp(o.amp);
      s += `<path d="M${MO.x - w} ${MO.y - 4} Q${MO.x} ${MO.y - 12} ${MO.x + w} ${MO.y - 4} Q${MO.x + w * .7} ${MO.y + h} ${MO.x} ${MO.y + h} Q${MO.x - w * .7} ${MO.y + h} ${MO.x - w} ${MO.y - 4} Z" fill="#fff"/><ellipse cx="${MO.x}" cy="${MO.y + h * .62}" rx="${w * .45}" ry="${h * .26}" fill="#f2a9a3"/>`;
    } else if (o.mood === "worried" || o.mood === "sad") {
      s += `<path d="M${MO.x - 30} ${MO.y + 16} Q${MO.x} ${MO.y - 4} ${MO.x + 30} ${MO.y + 16}" stroke="#fff" stroke-width="11" fill="none" stroke-linecap="round"/>`;
    } else if (o.mood === "sleepy") {
      s += `<path d="M${MO.x - 16} ${MO.y + 4} Q${MO.x} ${MO.y + 12} ${MO.x + 16} ${MO.y + 4}" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round"/>`;
    } else {
      const big = o.mood === "happy" ? 1.3 : 1;
      s += `<path d="M${MO.x - 34 * big} ${MO.y - 2} Q${MO.x} ${MO.y + 30 * big} ${MO.x + 34 * big} ${MO.y - 2}" stroke="#fff" stroke-width="12" fill="none" stroke-linecap="round"/>`;
    }
    $("faceG").innerHTML = s;
  }

  /* ghost placement: [x, y, scale] key poses blended over time */
  const CORNER = [1736, 902, .43];
  const POSES = [
    [0, [960, 560, 1.0]],
    [S("L01") + 2.0, [1430, 560, .86]],
    [ACT2, CORNER],
    [CLOSE, [960, 420, .66]],
  ];
  function ghostPose(t) {
    let i = 0; for (let k = 0; k < POSES.length; k++) if (t >= POSES[k][0]) i = k;
    const a = POSES[Math.max(0, i - 1)][1], b = POSES[i][1], k = eio(P(t, POSES[i][0], 1.1));
    return [lerp(a[0], b[0], k), lerp(a[1], b[1], k), lerp(a[2], b[2], k)];
  }

  function renderGhost(t, f) {
    let [x, y, s] = ghostPose(t);
    const wake = P(t, .2, .9);
    let rot = Math.sin(t * 1.3) * 3, bob = Math.sin(t * 2.2) * (s > .7 ? 14 : 7);
    if (t < S("L01") + 1.4) rot += Math.sin(t * 8) * 7 * P(t, S("L01"), .3) * (1 - P(t, S("L01") + 1.1, .3)); // wave hello
    if (t > CLOSE + 1.2) rot += Math.sin(t * 6) * 4;
    const Wd = 640 * s, Hd = 579 * s, sq = 1 + Math.sin(t * 4.4) * .018;
    const G = $("ghost");
    G.style.width = Wd + "px"; G.style.height = Hd + "px";
    G.style.transform = `translate(${x - Wd / 2}px, ${y - Hd / 2 + bob}px) rotate(${rot}deg) scale(${1 / sq}, ${sq})`;
    G.style.opacity = clamp(wake * 1.5);
    const sh = $("shadow");
    sh.style.transform = `translate(${x - 170 * s * 1.5}px, ${y + Hd * .5}px) scale(${s * 1.5 * (1 - bob / 220)}, ${s * 1.3})`;
    sh.style.opacity = clamp(wake * 1.5) * .85;

    const amp = AMP[f] || 0;
    const bl = (t + .3) % 3.9; let open = bl < .07 ? 1 - bl / .07 : bl < .14 ? (bl - .07) / .07 : 1;
    let mood = "normal", gx = .2, gy = 0, wide = false, wink = false, brow = false;
    if (t < S("L01") - .15) { mood = "sleepy"; open = .15; }
    else if (t < S("L01") + 1.2) mood = "happy";
    const l = lineAt(t), sc = l ? l.scene : "";
    if (t >= S("L02") && t < ACT2) gx = -1;                         // looks at the act-1 graphics on its left
    if (t >= ACT2 && t < CLOSE) { gx = -1; gy = -.35; }              // looks up-left at the screen
    if (sc === "landing" && t > W("L03", "wrong") - .1) mood = "worried";
    if (sc === "neatlogs") mood = "worried";
    if (sc === "warning") { wide = true; brow = true; }
    if (sc === "incident" && t < W("L09", "noticed") + .6) wide = true;
    if (sc === "pr" || (sc === "slack" && t > W("L13", "three"))) mood = "happy";
    if (t > CLOSE + .3) { gx = .1; gy = 0; mood = "happy"; wink = t > W("L19", "night") && t < W("L19", "night") + .7; }
    if (mood === "happy" && amp > .07) mood = "normal";
    face({ open, gx, gy, mood, amp: mood === "sleepy" ? 0 : amp, wide, wink, brow });
  }

  /* -------- the browser card (footage lives inside it) -------- */
  const URLS = { proof: "nightly.whyparabola.online", scout: "nightly.whyparabola.online/app/agents/scout", ship: "nightly.whyparabola.online/app/agents/scout",
    neatlogs: "app.neatlogs.com/traces", incident: "nightly.whyparabola.online/app/incidents", warning: "nightly.whyparabola.online/app/incidents",
    entire: "entire.io/gh/e-man07/nightly", price: "app.cfo.ai", slack: "app.slack.com", pr: "github.com/e-man07/nightly/pull/43",
    sponsors: "nightly.whyparabola.online", "neatlogs-card": "app.neatlogs.com/traces", "entire-card": "entire.io/gh/e-man07/nightly", "cfo-card": "app.cfo.ai" };
  function renderCard(t) {
    const inK = eout(P(t, ACT2, .9)), outK = P(t, CLOSE, .7);
    const c = $("card");
    c.style.opacity = clamp(inK * 1.4) * (1 - outK);
    c.style.transform = `translateY(${(1 - inK) * 70 + outK * 40}px) scale(${.96 + .04 * inK})`;
    const l = lineAt(t);
    const sc = l && t >= ACT2 ? l.scene : "proof";
    $("url").textContent = URLS[sc] || URLS.proof;
    const ph = $("ph");
    if (ph) ph.textContent = window.HAS_FOOTAGE ? "" : `[ footage · ${sc} ]`;
    const dimK = t >= ACT4 && t < S("L16") - .2 ? eout(P(t, ACT4, .5)) * .82 : 0;
    $("dim").style.opacity = dimK;
  }

  /* -------- right rail: what's happening, one step at a time -------- */
  function railChip(t, at, icon, color, label) {
    const p = pop(t, at);
    return `<div class="chip" style="margin-bottom:12px;${st(p)}"><span class="ic" style="background:${color}">${I[icon]}</span>${label}</div>`;
  }
  function renderRail(t) {
    if (t < ACT2 + .4 || t > CLOSE) { $("rail").innerHTML = ""; return; }
    const l = lineAt(t), sc = l.scene;
    let h = "";
    const head = (at, html) => { const p = pop(t, at, .5); return `<div style="${st(p)}">${html}</div>`; };
    if (sc === "proof") {
      h += head(S("L04"), `<div class="sub" style="font-size:19px;letter-spacing:.06em;text-transform:uppercase;color:#a99fe0">Nightly is</div><div style="font:700 34px/1.12 Geist;color:#fff;margin:8px 0 22px">The on-call engineer for your AI agents</div>`);
      h += railChip(t, W("L05", "notice"), "eye", "#6c5ce7", "Notices");
      h += railChip(t, W("L05", "find"), "find", "#2f5bd3", "Finds the cause");
      h += railChip(t, W("L05", "work"), "usd", "#b06a00", "Prices it");
      h += railChip(t, W("L05", "fix"), "fix", "#18804a", "Fixes what's safe");
      h += railChip(t, W("L05", "prove"), "check", "#18804a", "Proves it");
      h += railChip(t, W("L05", "message"), "msg", "#2a2340", "Tells you once");
      h += railChip(t, W("L05", "anything"), "hand", "#e0502b", "Risky? Asks first");
    } else if (sc === "scout") {
      h += head(S("L06") + .2, `<div style="margin-bottom:22px">${tagHTML("neatlogs", "")}</div><div class="big" style="font-size:52px">Scout</div><div class="sub" style="margin-top:10px">A support bot for a product's docs. Every answer traced.</div>`);
      h += head(W("L06", "connect"), `<div class="chip" style="margin-top:26px;font-family:'Geist Mono';font-size:19px"><span class="ic" style="background:#2a2340">${I.code}</span>pip install nightly-sdk</div>`);
    } else if (sc === "ship") {
      h += head(S("L07") + .1, `<div class="sub" style="font-size:19px;letter-spacing:.06em;text-transform:uppercase;color:#a99fe0;margin-bottom:12px">Ask to a coding agent</div><div class="quote" style="background:#fff;border-color:#d9d4f0;color:#17122f">“Upgrade Scout to the newest Claude model.”</div>`);
      h += head(W("L07", "ships"), `<div class="chip" style="margin-top:22px"><span class="ic" style="background:#e0502b">${I.code}</span>Release s5 shipped</div>`);
    } else if (sc === "neatlogs") {
      h += head(S("L08"), `<div style="margin-bottom:22px">${tagHTML("neatlogs", "")}</div><div class="big" style="color:#ff8a6b">Every answer fails</div>`);
      h += head(W("L08", "still"), `<div class="chip" style="margin-top:22px;color:#157a45"><span class="ic" style="background:#18804a">${I.check}</span>HTTP 200 OK</div><div class="sub" style="margin-top:12px">…so nothing pages anyone.</div>`);
    } else if (sc === "incident") {
      h += head(W("L09", "twenty"), `<div class="big" style="font-size:118px">22<span style="font-size:58px"> s</span></div><div class="sub" style="margin-top:6px">to notice</div>`);
      h += railChip(t, W("L09", "read"), "eye", "#6c5ce7", "Read the traces");
      h += railChip(t, W("L09", "see"), "find", "#2f5bd3", "Saw what shipped");
      h += railChip(t, W("L09", "exact"), "code", "#e0502b", "Found the line");
    } else if (sc === "warning") {
      h += head(S("L10") + .3, `<div class="sub" style="font-size:19px;letter-spacing:.06em;text-transform:uppercase;color:#f3c56b;margin-bottom:12px">The coding agent said</div><div class="quote">“Check that this model exists… or it'll fail.”</div>`);
    } else if (sc === "entire") {
      h += head(S("L11"), `<div style="margin-bottom:22px">${tagHTML("entire", "")}</div>`);
      h += railChip(t, W("L11", "prompt"), "msg", "#2a2340", "The prompt");
      h += railChip(t, W("L11", "agent"), "code", "#2a2340", "The agent's notes");
      h += head(W("L11", "nobody"), `<div style="font:600 25px/1.3 Geist;color:#fff;margin-top:20px">Nobody read it at 5 p.m.</div><div style="font:700 25px/1.3 Geist;color:#b8a6ff">I read it at 3 a.m.</div>`);
    } else if (sc === "price") {
      h += head(S("L12"), `<div style="margin-bottom:22px">${tagHTML("cfo", "")}</div>`);
      h += head(W("L12", "hundred"), `<div class="big" style="font-size:76px;color:#ffb35c">$113<span style="font-size:36px">/min</span></div>`);
      h += head(W("L12", "nearly"), `<div class="big" style="font-size:52px;margin-top:20px">$1,699</div><div class="sub" style="margin-top:6px">if we wait for someone to wake up</div>`);
      h += head(W("L12", "worth"), `<div class="chip" style="margin-top:22px"><span class="ic" style="background:#18804a">${I.check}</span>Worth fixing now</div>`);
    } else if (sc === "slack") {
      h += railChip(t, W("L13", "roll"), "fix", "#18804a", "Rolled back on its own");
      h += head(W("L13", "three"), `<div class="big" style="font-size:86px;margin:16px 0 4px">3/3</div><div class="sub" style="margin-bottom:22px">failed chats now fixed</div>`);
      h += railChip(t, W("L13", "send"), "msg", "#2a2340", "One message");
      h += railChip(t, W("L13", "undo"), "fix", "#e0502b", "…with an undo button");
    } else if (sc === "pr") {
      h += head(S("L14") + .1, `<div class="sub" style="font-size:19px;letter-spacing:.06em;text-transform:uppercase;color:#a99fe0;margin-bottom:14px">Your call</div>`);
      h += railChip(t, W("L14", "approve"), "check", "#18804a", "You approve");
      h += railChip(t, W("L14", "pull"), "code", "#2a2340", "Fix PR + write-up");
      h += railChip(t, W("L14", "test"), "check", "#2f5bd3", "A test, so it can't come back");
    } else if (sc === "neatlogs-card" || sc === "entire-card" || sc === "cfo-card") {
      const word = { "neatlogs-card": "Eyes", "entire-card": "Memory", "cfo-card": "Money" }[sc];
      h += head(l.start, `<div class="sub" style="font-size:19px;letter-spacing:.06em;text-transform:uppercase;color:#a99fe0">My</div><div class="big" style="font-size:80px">${word}</div>`);
    }
    $("rail").innerHTML = h;
  }

  /* -------- stage: act 1 story, sponsor cards, interstitial, end card -------- */
  function renderStage(t) {
    let h = "";
    const fade = (a, b, d = .4) => clamp(P(t, a, d)) * (1 - P(t, b, d));
    if (t < ACT2 + .3) {
      const out = 1 - P(t, ACT2 - .2, .5);
      // headline swaps phrase by phrase
      const heads = [
        [S("L01"), W("L01", "here"), `Hey, I'm <em>Nightly</em>.`],
        [W("L01", "here"), S("L02"), `A problem nobody <em>talks about</em>.`],
        [S("L02"), W("L02", "and"), `AI agents run <em>all night</em>.`],
        [W("L02", "and"), S("L03"), `When one breaks, it <em>doesn't crash</em>.`],
        [S("L03"), W("L03", "your"), `It gives <em>wrong answers</em>.`],
        [W("L03", "your"), ACT2, `Dashboards stay <em>green</em>.`],
      ];
      for (const [a, b, html] of heads) {
        const k = fade(a, b, .35);
        if (k > .001) h += `<div class="h1 abs" style="left:140px;top:${t < S("L02") ? 430 : 210}px;width:1100px;opacity:${k * out};transform:translateY(${(1 - eout(P(t, a, .45))) * 30}px)">${html}</div>`;
      }
      // the three jobs agents do at night
      if (t >= S("L02") && t < W("L02", "and") + 1.2) {
        const o = (1 - P(t, W("L02", "and") + .4, .6)) * out;
