/* Nightly launch film — the whole picture as one pure function render(t).
   HyperFrames seeks it through the adapter hook on window.__hfAnime (seek / pause / play). */
(function () {
  const TL = window.TL, AMP = window.AMP || [], FPS = TL.fps, SHOTS = window.SHOTS || [];
  const LN = Object.fromEntries(TL.lines.map(l => [l.id, l]));
  const $ = id => document.getElementById(id);
  const clamp = (x, a = 0, b = 1) => Math.max(a, Math.min(b, x));
  const lerp = (a, b, k) => a + (b - a) * k;
  const eio = k => (k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2);
  const eout = k => 1 - Math.pow(1 - k, 3);
  const P = (t, a, d) => clamp((t - a) / d);
  const S = id => LN[id].start, E = id => LN[id].end;
  const W = (id, w, from = 0) => {
    const ws = LN[id].words;
    for (let i = from; i < ws.length; i++) if (ws[i].w.toLowerCase().replace(/[^a-z0-9$']/g, "").startsWith(w.toLowerCase())) return ws[i].s;
    return LN[id].start;
  };
  const fade = (t, a, b, d = .45) => clamp(P(t, a, d)) * (1 - P(t, b, d));
  const rise = (t, a, d = .7) => { const k = eout(P(t, a, d)); return `opacity:${clamp(P(t, a, d * .7))};transform:translateY(${(1 - k) * 26}px)`; };

  const ACT2 = S("L04") - .5, ACT4 = S("L15") - .35, CLOSE = S("L19") - .45;
  const FW = 1600, FH = 917;

  /* ---------------- sky: sparse stars (fixed seed), film grain (pre-baked, cycled per frame) ---------------- */
  let seed = 9;
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  (function stars() {
    const c = $("stars").getContext("2d");
    for (let i = 0; i < 120; i++) {
      const x = rnd() * 1920, y = rnd() * 640, r = rnd() * 1.1 + .25;
      c.fillStyle = `rgba(225,232,255,${.08 + rnd() * .38})`;
      c.beginPath(); c.arc(x, y, r, 0, 6.283); c.fill();
    }
  })();
  const GRAIN = [];
  for (let g = 0; g < 4; g++) {
    const cv = document.createElement("canvas"); cv.width = 960; cv.height = 540;
    const cx = cv.getContext("2d"), im = cx.createImageData(960, 540);
    for (let i = 0; i < im.data.length; i += 4) { const v = 128 + (rnd() - .5) * 120; im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = 255; }
    cx.putImageData(im, 0, 0); GRAIN.push(cv);
  }
  const grainCtx = $("grain").getContext("2d");

  /* ---------------- ghost (the published explainer's rig) ---------------- */
  const EL = { x: 731, y: 471, rx: 47, ry: 64 }, ER = { x: 975, y: 442, rx: 39, ry: 58 }, MO = { x: 878, y: 506 };
  function face(o) {
    const eye = (Ei, open, closedStyle) => {
      if (o.mood === "happy" || closedStyle) return `<path d="M${Ei.x - Ei.rx * .8} ${Ei.y + 8} Q${Ei.x} ${Ei.y - Ei.ry * .55} ${Ei.x + Ei.rx * .8} ${Ei.y + 8}" stroke="#fff" stroke-width="15" fill="none" stroke-linecap="round"/>`;
      if (open < .22) return `<path d="M${Ei.x - Ei.rx * .85} ${Ei.y + 6} Q${Ei.x} ${Ei.y + 22} ${Ei.x + Ei.rx * .85} ${Ei.y + 6}" stroke="#fff" stroke-width="13" fill="none" stroke-linecap="round"/>`;
      const ry = Ei.ry * open * (o.wide ? 1.12 : 1), rx = Ei.rx * (o.wide ? 1.08 : 1);
      const px = Ei.x + o.gx * Ei.rx * .38, py = Ei.y + o.gy * Ei.ry * .3 + Ei.ry * .08;
      return `<ellipse cx="${Ei.x}" cy="${Ei.y}" rx="${rx}" ry="${ry}" fill="#fff"/><clipPath id="c${Ei.x}"><ellipse cx="${Ei.x}" cy="${Ei.y}" rx="${rx}" ry="${ry}"/></clipPath>
        <g clip-path="url(#c${Ei.x})"><ellipse cx="${px}" cy="${py}" rx="${rx * .56}" ry="${Ei.ry * .62}" fill="#0d0c12"/><circle cx="${px + rx * .18}" cy="${py - Ei.ry * .22}" r="${rx * .17}" fill="#fff"/></g>`;
