    renderCaption(t);
    grainCtx.clearRect(0, 0, 960, 540);
    grainCtx.drawImage(GRAIN[f % 4], 0, 0);
  }

  window.__hfAnime = window.__hfAnime || [];
  window.__hfAnime.push({ seek(ms) { render(ms / 1000); }, pause() {}, play() {} });
  render(0);
})();

